450	  function getCountdownData(cutoffTime) {
451	    if (!cutoffTime) return null;
452	    var parts = cutoffTime.split(':');
453	    var cutoffHr = parseInt(parts[0], 10);
454	    var cutoffMin = parseInt(parts[1] || '0', 10);
455	    var now = new Date();
456	    var cutoff = new Date();
457	    cutoff.setHours(cutoffHr, cutoffMin, 0, 0);
458	    var diff = cutoff - now;
459	    if (diff <= 0) return { passed: true, hours: 0, minutes: 0 };
460	    var hours = Math.floor(diff / 3600000);
461	    var minutes = Math.floor((diff % 3600000) / 60000);
462	    return { passed: false, hours: hours, minutes: minutes };
463	  }
