1235	        '<div id="' + WID + '" data-zcc-widget="true" style="border:none !important;box-shadow:none !important;max-width:none !important;padding:16px 24px 24px !important">' +
1236	          buildWidgetInner(WID, cfg, cfg.buttonText, false) +
1237	        '</div>' +
1238	      '</div>';
1239	    document.body.appendChild(overlay);
1240	
1241	    var trigger = document.getElementById(WID + "-popup-trigger");
1242	    var closeBtn = document.getElementById(WID + "-modal-close");
1243	    var modal = document.getElementById(WID + "-modal");
1244	
1245	    function openPopup() { overlay.classList.add("zcc-open"); }
1246	    function closePopup() { overlay.classList.remove("zcc-open"); }
1247	
1248	    if (trigger) trigger.addEventListener("click", openPopup);
1249	    if (closeBtn) closeBtn.addEventListener("click", closePopup);
1250	
1251	    // Close on overlay backdrop click (not modal content)
1252	    overlay.addEventListener("click", function (e) {
1253	      if (e.target === overlay) closePopup();
1254	    });
1255	
1256	    // Close on Escape key
1257	    document.addEventListener("keydown", function (e) {
1258	      if (e.key === "Escape") closePopup();
1259	    });
1260	
1261	    wireWidget(WID, cfg, API_BASE, SHOP);
1262	  }
1263	
1264	  function esc(str) {
1265	    return String(str)
1266	      .replace(/&/g, "&amp;")
1267	      .replace(/</g, "&lt;")
1268	      .replace(/>/g, "&gt;")
1269	      .replace(/"/g, "&quot;");
1270	  }
1271	
1272	  function escAttr(str) {
1273	    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
1274	  }
1275	  } // end init()
1276	})();
1277	</script>
